import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  const weatherSchema = {
    type: 'object',
    properties: {location: {type: 'string'}},
    required: ['location'],
  };

  const registerWeather = (registry: ToolRegistry, executor: Parameters<ToolRegistry['register']>[1]): void => {
    registry.register({name: 'weather', description: 'Get weather', inputSchema: weatherSchema}, executor);
  };

  const countCompiles = (registry: ToolRegistry): {get: () => number} => {
    let compileCalls = 0;
    const ajv = (
      registry as unknown as {
        ajv: {compile: (inputSchema: Record<string, unknown>) => unknown};
      }
    ).ajv;
    const originalCompile = ajv.compile.bind(ajv);
    ajv.compile = inputSchema => {
      compileCalls += 1;
      return originalCompile(inputSchema);
    };
    return {get: () => compileCalls};
  };

  const executeTenTimes = async (registry: ToolRegistry): Promise<void> => {
    for (let call = 0; call < 10; call += 1) {
      await registry.execute('weather', {location: 'Paris'});
    }
  };

  it('rejects input missing a required property without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'city_forecast',
        description: 'Get a forecast for a city',
        inputSchema: {
          type: 'object',
          properties: {city: {type: 'string'}},
          required: ['city'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'clear';
      }
    );

    const response = await registry.execute('city_forecast', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: expect.stringContaining('city'),
    });
  });

  it('rejects a wrong-typed nested property with a redacted path-aware message', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;

    registry.register(
      {
        name: 'lookup_profile',
        description: 'Look up a profile by display name',
        inputSchema: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {displayName: {type: 'string'}},
              required: ['displayName'],
            },
          },
          required: ['profile'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_profile', {profile: {displayName: 987654321}});

    expect({
      executorCalls,
      result: response.result,
      leaksValue: response.result.includes('987654321'),
    }).toEqual({
      executorCalls: 0,
      result: '/profile/displayName must be string',
      leaksValue: false,
    });
  });

  it('passes valid input with extra properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', requestedBy: 'Ada'};
    let executorCalls = 0;
    let received: Record<string, unknown> | undefined;
    const executor = async (executorInput: Record<string, unknown>) => {
      executorCalls += 1;
      received = executorInput;
      return 'clear';
    };

    registerWeather(registry, executor);

    await registry.execute('weather', input);

    expect({calls: executorCalls, received}).toEqual({
      calls: 1,
      received: input,
    });
  });

  it('compiles a function-source schema once when the same schema object is reused', async () => {
    const registry = new ToolRegistry();
    const schema = weatherSchema;
    const compileCounter = countCompiles(registry);

    registry.register(
      () => ({name: 'weather', description: 'Get weather', inputSchema: schema}),
      async () => 'clear'
    );

    await executeTenTimes(registry);

    expect(compileCounter.get()).toBe(1);
  });

  it('validates function-source input against the schema returned for each call', async () => {
    const registry = new ToolRegistry();
    let useLocationSchema = true;
    let executorCalls = 0;
    const executor = async () => {
      executorCalls += 1;
      return 'clear';
    };

    registry.register(
      () => ({
        name: 'weather',
        description: 'Get weather',
        inputSchema: useLocationSchema
          ? {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}
          : {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
      }),
      executor
    );

    const firstResponse = await registry.execute('weather', {location: 'Paris'});
    useLocationSchema = false;
    const secondResponse = await registry.execute('weather', {location: 'Paris'});
    expect({
      firstResult: firstResponse.result,
      secondResult: secondResponse.result,
      executorCalls,
    }).toEqual({
      firstResult: 'clear',
      secondResult: expect.stringContaining('city'),
      executorCalls: 1,
    });
  });

  it('compiles a static schema once across repeated executions', async () => {
    const registry = new ToolRegistry();
    const compileCounter = countCompiles(registry);

    registerWeather(registry, async () => 'clear');

    await executeTenTimes(registry);

    expect(compileCounter.get()).toBe(1);
  });

  it('throws the unchanged unknown-tool error', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_weather', {})).rejects.toThrow('Unknown tool: missing_weather');
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | Shipped              |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16); [validated by: rejects input missing a required property without calling the executor](../../src/orchestration/tools/registry.test.ts#L30)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46); [validated by: rejects a wrong-typed nested property with a redacted path-aware message](../../src/orchestration/tools/registry.test.ts#L58)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with extra properties through unchanged exactly once](../../src/orchestration/tools/registry.test.ts#L97)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.
  ([validated by: throws the unchanged unknown-tool error](../../src/orchestration/tools/registry.test.ts#L175))

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static schema once across repeated executions](../../src/orchestration/tools/registry.test.ts#L162)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: compiles a function-source schema once when the same schema object is reused](../../src/orchestration/tools/registry.test.ts#L113); [validated by: validates function-source input against the schema returned for each call](../../src/orchestration/tools/registry.test.ts#L130)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112); [validated by: returns schema rejection to the provider so a corrected retry can complete the turn](../../src/orchestration/chatOrchestrator.test.ts#L401)).
